/* Mobile-first optimizations for Better Pack */

/* Ensure touch targets are at least 44x44px for mobile accessibility */
@media (max-width: 768px) {
  /* Make all interactive elements touch-friendly */
  button,
  input,
  select,
  textarea,
  a {
    min-height: 44px;
  }

  /* Improve tap target spacing */
  .space-y-4 > * {
    margin-bottom: 1rem;
  }

  /* Sticky save buttons on mobile */
  .mobile-sticky-footer {
    position: sticky;
    bottom: 0;
    background: white;
    border-top: 1px solid #e5e7eb;
    padding: 1rem;
    margin: -1rem -1rem 0;
    z-index: 10;
  }

  /* Full-width buttons on mobile */
  .mobile-full-button {
    width: 100%;
  }

  /* Better input focus states for mobile */
  input:focus,
  select:focus,
  textarea:focus {
    outline: 3px solid rgba(59, 130, 246, 0.5);
    outline-offset: 2px;
  }

  /* Larger text for better readability */
  input,
  select,
  textarea {
    font-size: 16px; /* Prevents zoom on iOS */
  }

  /* Better select dropdowns */
  select {
    background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e");
    background-position: right 0.5rem center;
    background-repeat: no-repeat;
    background-size: 1.5em 1.5em;
    padding-right: 2.5rem;
  }

  /* Improve number input buttons */
  input[type="number"]::-webkit-inner-spin-button,
  input[type="number"]::-webkit-outer-spin-button {
    height: 44px;
    opacity: 1;
  }

  /* Better checkbox and radio buttons */
  input[type="checkbox"],
  input[type="radio"] {
    width: 20px;
    height: 20px;
    cursor: pointer;
  }

  /* Card spacing on mobile */
  .mobile-card {
    margin: 0.5rem;
    border-radius: 0.75rem;
  }

  /* Swipe hint for horizontally scrollable content */
  .mobile-scroll-hint {
    position: relative;
  }

  .mobile-scroll-hint::after {
    content: '';
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 30px;
    background: linear-gradient(to left, rgba(255,255,255,1), rgba(255,255,255,0));
    pointer-events: none;
  }

  /* Better modal/drawer positioning */
  .mobile-drawer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    max-height: 90vh;
    border-top-left-radius: 1rem;
    border-top-right-radius: 1rem;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }
}

/* Landscape mode adjustments */
@media (max-height: 500px) and (orientation: landscape) {
  .mobile-sticky-footer {
    position: relative;
  }

  .mobile-drawer {
    max-height: 80vh;
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  button,
  input,
  select,
  textarea {
    border-width: 2px;
  }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .mobile-sticky-footer {
    background: #1f2937;
    border-top-color: #374151;
  }
}

/* Reduce motion for accessibility */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

