      setName('')
      setBrand('')
      setWeightValue('')
      setCategory('Other')
      setQuantity(1)
      setWorn(false)
      setConsumable(false)
      setPrice('')
      setModel('')
      setDescription('')
      setImageUrl('')
      setNotes('')
      setShowAdvanced(false)

