import { useState } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import { AddGearForm } from './AddGearForm'
import type { GearItem } from '@/types/database'

interface AddGearFormWrapperProps {
  onAdd: (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onCancel?: () => void
  simplified?: boolean
  isOpen?: boolean
}

export function AddGearFormWrapper({ 
  onAdd, 
  onCancel, 
  simplified = false,
  isOpen = true
}: AddGearFormWrapperProps) {
  const [loading, setLoading] = useState(false)

  const handleAdd = async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    setLoading(true)
    try {
      await onAdd(gear)
      // Don't close automatically - let parent handle it
    } finally {
      setLoading(false)
    }
  }

  return (
    <MobileFormDrawer
      isOpen={isOpen}
      onClose={onCancel || (() => {})}
      title="Add Gear"
      primaryAction={
        onCancel ? {
          label: 'Add Gear',
          onClick: () => {
            // The form will handle its own submission via form onSubmit
            const form = document.querySelector('form[data-add-gear-form]') as HTMLFormElement
            if (form) {
              form.requestSubmit()
            }
          },
          loading
        } : undefined
      }
      secondaryAction={
        onCancel ? {
          label: 'Cancel',
          onClick: onCancel
        } : undefined
      }
    >
      <div className="p-6">
        <AddGearForm
          onAdd={handleAdd}
          onCancel={onCancel}
          simplified={simplified}
        />
      </div>
    </MobileFormDrawer>
  )
}

