import { useState, useRef, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { ChevronDown, ChevronUp, X } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { convertToGrams, convertFromGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { ImageUploadField } from './ImageUploadField'

interface EditGearFormProps {
  item: GearItem
  onUpdate: (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onCancel: () => void
}

export function EditGearForm({ item, onUpdate, onCancel }: EditGearFormProps) {
  const [formData, setFormData] = useState({
    name: item.name,
    brand: item.brand || '',
    model: item.model || item.description || '', // Use model if available, fall back to description for backwards compatibility
    category: item.category,
    quantity: item.quantity,
    worn: item.worn,
    consumable: item.consumable,
    price: item.price || '',
    notes: item.notes || '',
    description: item.description || '',
    image_url: item.image_url || '',
  })

  // Weight handling
  const [weightValue, setWeightValue] = useState(() => {
    // Start with grams by default
    return item.weight_grams.toString()
