import { useState, useRef, useEffect } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { SimpleSelect } from '@/components/ui/select'
import { ChevronDown, ChevronUp } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { ImageUploadField } from './ImageUploadField'

interface EditGearFormProps {
  item: GearItem
  onUpdate: (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onCancel: () => void
}

export function EditGearForm({ item, onUpdate, onCancel }: EditGearFormProps) {
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: item.name,
    brand: item.brand || '',
    model: item.model || item.description || '',
    category: item.category,
    quantity: item.quantity,
    worn: item.worn,
    consumable: item.consumable,
    price: item.price || '',
    notes: item.notes || '',
    description: item.description || '',
    image_url: item.image_url || '',
  })

  const [weightValue, setWeightValue] = useState(() => {
    return item.weight_grams.toString()
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>('g')
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [weightError, setWeightError] = useState('')
  const nameInputRef = useRef<HTMLInputElement>(null)

  const handleWeightBlur = () => {
    const parsed = parseWeightInput(weightValue)
    if (parsed) {
      setWeightValue(parsed.value.toString())
      setWeightUnit(parsed.unit)
      setWeightError('')
    }
  }

  const getWeightInGrams = (): number => {
    const value = parseFloat(weightValue)
    if (isNaN(value)) return 0
    return Math.round(convertToGrams(value, weightUnit))
  }

  const getWeightPreview = (): string => {
    const grams = getWeightInGrams()
    if (grams === 0) return ''

    const units: WeightUnit[] = ['g', 'oz', 'lb', 'kg']
    const previews = units
      .filter(u => u !== weightUnit)
      .map(u => formatWeightWithUnit(grams, u))

    return `(${previews.join(' / ')})`
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    try {
      const weightNum = parseFloat(weightValue)
      if (isNaN(weightNum) || weightNum <= 0) {
        setWeightError('Please enter a valid weight')
        return
      }

      const weightGrams = getWeightInGrams()

      const updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>> = {
        name: formData.name.trim(),
        brand: formData.brand.trim() || null,
        model: formData.model.trim() || null,
        category: formData.category,
        weight_grams: weightGrams,
        quantity: formData.quantity,
        worn: formData.worn,
        consumable: formData.consumable,
        price: formData.price ? Number(formData.price) : null,
        notes: formData.notes.trim() || null,
        description: formData.description.trim() || null,
        image_url: formData.image_url.trim() || null,
      }

      await onUpdate(item.id, updates)
    } finally {
      setLoading(false)
    }
  }

  return (
    <MobileFormDrawer
      isOpen={true}
      onClose={onCancel}
      title="Edit Gear Item"
      primaryAction={{
        label: 'Update Item',
        onClick: () => {
          const form = document.querySelector('form[data-edit-gear-form]') as HTMLFormElement
          if (form) {
            form.requestSubmit()
          }
        },
        loading
      }}
      secondaryAction={{
        label: 'Cancel',
        onClick: onCancel
      }}
    >
      <div className="p-6">
        <form 
          onSubmit={handleSubmit}
          className=""
          data-edit-gear-form
        >
          <div className="space-y-4">
            {/* Name and Brand */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="edit-name">
                  Name <span className="text-red-500">*</span>
                </Label>
                <Input
                  ref={nameInputRef}
                  id="edit-name"
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., Backpack"
                  required
                  className="min-h-[44px]"
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="edit-brand">Brand</Label>
                <Input
                  id="edit-brand"
                  type="text"
                  value={formData.brand}
                  onChange={(e) => setFormData({ ...formData, brand: e.target.value })}
                  placeholder="e.g., Gossamer Gear"
                  className="min-h-[44px]"
                />
              </div>
            </div>

            {/* Model and Category */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="edit-model">Model</Label>
                <Input
                  id="edit-model"
                  type="text"
                  value={formData.model}
                  onChange={(e) => setFormData({ ...formData, model: e.target.value })}
                  placeholder="e.g., Mariposa 60L"
                  className="min-h-[44px]"
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="edit-category">Category</Label>
                <SimpleSelect
                  value={formData.category}
                  onChange={(value) => setFormData({ ...formData, category: value })}
                  options={GEAR_CATEGORIES}
                />
              </div>
            </div>

            {/* Weight */}
            <div className="flex flex-col gap-2">
              <Label htmlFor="edit-weight">
                Weight <span className="text-red-500">*</span>
              </Label>
              <div className="flex gap-2">
                <Input
                  id="edit-weight"
                  type="number"
                  step="0.1"
                  value={weightValue}
                  onChange={(e) => {
                    setWeightValue(e.target.value)
                    setWeightError('')
                  }}
                  onBlur={handleWeightBlur}
                  placeholder="Weight"
                  required
                  className={`flex-1 min-h-[44px] ${weightError ? 'border-red-500' : ''}`}
                  inputMode="decimal"
                />
                <SimpleSelect
                  value={weightUnit}
                  onChange={(value) => setWeightUnit(value as WeightUnit)}
                  options={['g', 'oz', 'lb', 'kg']}
                  className="min-w-[70px]"
                />
              </div>
              {weightError && (
                <p className="text-red-500 text-sm">{weightError}</p>
              )}
              {getWeightPreview() && (
                <p className="text-sm text-muted-foreground">{getWeightPreview()}</p>
              )}
            </div>

            {/* Advanced Options Toggle */}
            <button
              type="button"
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
            >
              {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
              {showAdvanced ? 'Hide' : 'Show'} advanced options
            </button>

            {/* Advanced Fields */}
            {showAdvanced && (
              <div className="space-y-4 pt-2 border-t">
                {/* Quantity and Price */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="flex flex-col gap-2">
                    <Label htmlFor="edit-quantity">Quantity</Label>
                    <Input
                      id="edit-quantity"
                      type="number"
                      value={formData.quantity}
                      onChange={(e) => setFormData({ ...formData, quantity: parseInt(e.target.value) || 1 })}
                      min="1"
                      className="min-h-[44px]"
                      inputMode="numeric"
                    />
                  </div>
                  <div className="flex flex-col gap-2">
                    <Label htmlFor="edit-price">Price ($)</Label>
                    <Input
                      id="edit-price"
                      type="number"
                      step="0.01"
                      value={formData.price}
                      onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                      placeholder="0.00"
                      className="min-h-[44px]"
                      inputMode="decimal"
                    />
                  </div>
                </div>

                {/* Description and Image URL */}
                <div className="space-y-4">
                  <div className="flex flex-col gap-2">
                    <Label htmlFor="edit-description">Description</Label>
                    <Textarea
                      id="edit-description"
                      value={formData.description}
                      onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                      placeholder="Detailed description..."
                      className="min-h-[80px]"
                    />
                  </div>
                  <div className="flex flex-col gap-2">
                    <Label htmlFor="edit-image">Image URL</Label>
                    <Input
                      id="edit-image"
                      type="url"
                      value={formData.image_url}
                      onChange={(e) => setFormData({ ...formData, image_url: e.target.value })}
                      placeholder="https://example.com/image.jpg"
                      className="min-h-[44px]"
                    />
                  </div>
                  <div className="flex flex-col gap-2">
                    <Label htmlFor="edit-notes">Notes</Label>
                    <Textarea
                      id="edit-notes"
                      value={formData.notes}
                      onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                      placeholder="Personal notes..."
                      className="min-h-[80px]"
                    />
                  </div>
                </div>

                {/* Checkboxes */}
                <div className="flex gap-6">
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={formData.worn}
                      onChange={(e) => setFormData({ ...formData, worn: e.target.checked })}
                      className="min-h-[20px] min-w-[20px]"
                    />
                    <span className="text-sm">Worn</span>
                  </label>
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={formData.consumable}
                      onChange={(e) => setFormData({ ...formData, consumable: e.target.checked })}
                      className="min-h-[20px] min-w-[20px]"
                    />
                    <span className="text-sm">Consumable</span>
                  </label>
                </div>
              </div>
            )}
          </div>
        </form>
      </div>
    </MobileFormDrawer>
  )
}

