import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import { MobileFormDrawer } from '../mobile-form-drawer'

// Mock body style manipulation
const mockBodyStyle = {
  overflow: ''
}
Object.defineProperty(document.body, 'style', {
  value: mockBodyStyle
})

describe('MobileFormDrawer', () => {
  const defaultProps = {
    isOpen: true,
    onClose: jest.fn(),
    title: 'Test Form',
    children: <div>Form content</div>
  }

  beforeEach(() => {
    jest.clearAllMocks()
    mockBodyStyle.overflow = ''
  })

  it('should render when open', () => {
    render(<MobileFormDrawer {...defaultProps} />)

    expect(screen.getByText('Test Form')).toBeInTheDocument()
    expect(screen.getByText('Form content')).toBeInTheDocument()
  })

  it('should not render when closed', () => {
    render(<MobileFormDrawer {...defaultProps} isOpen={false} />)

    expect(screen.queryByText('Test Form')).not.toBeInTheDocument()
  })

  it('should call onClose when close button clicked', () => {
    const onClose = jest.fn()
    render(<MobileFormDrawer {...defaultProps} onClose={onClose} />)

    fireEvent.click(screen.getByRole('button', { name: /close/i }))
    expect(onClose).toHaveBeenCalled()
  })

  it('should call onClose when backdrop clicked', () => {
    const onClose = jest.fn()
    render(<MobileFormDrawer {...defaultProps} onClose={onClose} />)

    // Click the backdrop
    const backdrop = screen.getByText('Test Form').closest('[class*="fixed"]')
    fireEvent.click(backdrop!)
    expect(onClose).toHaveBeenCalled()
  })

  it('should call onClose when Escape key pressed', () => {
    const onClose = jest.fn()
    render(<MobileFormDrawer {...defaultProps} onClose={onClose} />)

    fireEvent.keyDown(document, { key: 'Escape' })
    expect(onClose).toHaveBeenCalled()
  })

  it('should prevent body scroll when open', () => {
    render(<MobileFormDrawer {...defaultProps} />)
    expect(mockBodyStyle.overflow).toBe('hidden')
  })

  it('should restore body scroll when closed', () => {
    const { rerender } = render(<MobileFormDrawer {...defaultProps} />)
    expect(mockBodyStyle.overflow).toBe('hidden')

    rerender(<MobileFormDrawer {...defaultProps} isOpen={false} />)
    expect(mockBodyStyle.overflow).toBe('')
  })

  it('should render primary action button', () => {
    const primaryAction = {
      label: 'Save',
      onClick: jest.fn(),
      disabled: false
    }

    render(
