import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import { Select, SimpleSelect } from '../select'

describe('Select Component', () => {
  const mockOptions = [
    { value: 'option1', label: 'Option 1' },
    { value: 'option2', label: 'Option 2' },
    { value: 'option3', label: 'Option 3' }
  ]

  it('should render with placeholder when no value selected', () => {
    render(
      <Select
        value=""
        onChange={jest.fn()}
        options={mockOptions}
        placeholder="Choose an option"
      />
    )

    expect(screen.getByText('Choose an option')).toBeInTheDocument()
  })

  it('should render with selected value', () => {
    render(
      <Select
        value="option2"
        onChange={jest.fn()}
        options={mockOptions}
      />
    )

    expect(screen.getByText('Option 2')).toBeInTheDocument()
  })

  it('should open dropdown when clicked', () => {
    render(
      <Select
        value=""
        onChange={jest.fn()}
        options={mockOptions}
        placeholder="Choose an option"
      />
    )

    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('listbox')).toBeInTheDocument()
  })

  it('should call onChange when option selected', () => {
    const onChange = jest.fn()
    render(
      <Select
        value=""
        onChange={onChange}
        options={mockOptions}
      />
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))

    // Click option
    fireEvent.click(screen.getByText('Option 2'))

    expect(onChange).toHaveBeenCalledWith('option2')
  })

  it('should close dropdown when option selected', () => {
    render(
      <Select
        value=""
        onChange={jest.fn()}
        options={mockOptions}
      />
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('listbox')).toBeInTheDocument()

    // Select option
    fireEvent.click(screen.getByText('Option 1'))

    // Should close
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
  })

  it('should close dropdown when clicking outside', async () => {
    render(
      <>
        <Select
          value=""
          onChange={jest.fn()}
          options={mockOptions}
        />
        <div data-testid="outside">Outside element</div>
      </>
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('listbox')).toBeInTheDocument()

    // Click outside
    fireEvent.mouseDown(screen.getByTestId('outside'))

    await waitFor(() => {
      expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
    })
  })

  it('should close dropdown when Escape pressed', async () => {
    render(
      <Select
        value=""
        onChange={jest.fn()}
        options={mockOptions}
      />
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByRole('listbox')).toBeInTheDocument()

    // Press Escape
    fireEvent.keyDown(document, { key: 'Escape' })

    await waitFor(() => {
      expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
    })
  })

  it('should navigate options with arrow keys', async () => {
    const onChange = jest.fn()
    render(
      <Select
        value="option1"
        onChange={onChange}
        options={mockOptions}
      />
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))

    // Press ArrowDown
    fireEvent.keyDown(document, { key: 'ArrowDown' })

    expect(onChange).toHaveBeenCalledWith('option2')
  })

  it('should handle disabled state', () => {
    render(
      <Select
        value=""
        onChange={jest.fn()}
        options={mockOptions}
        disabled={true}
      />
    )

    const button = screen.getByRole('button')
    expect(button).toBeDisabled()

    // Should not open when clicked
    fireEvent.click(button)
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
  })

  it('should show check mark for selected option', () => {
    render(
      <Select
        value="option2"
        onChange={jest.fn()}
        options={mockOptions}
      />
    )

    // Open dropdown
    fireEvent.click(screen.getByRole('button'))

    // Should show check mark next to selected option
    const selectedOption = screen.getByRole('option', { name: /option 2/i })
    expect(selectedOption).toHaveAttribute('aria-selected', 'true')
  })
})

describe('SimpleSelect Component', () => {
  it('should work with string array options', () => {
    const onChange = jest.fn()
    render(
      <SimpleSelect
        value="option2"
        onChange={onChange}
        options={['option1', 'option2', 'option3']}
      />
    )

    expect(screen.getByText('option2')).toBeInTheDocument()

    // Open and select different option
    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByText('option3'))

    expect(onChange).toHaveBeenCalledWith('option3')
  })

  it('should work with object array options', () => {
    const onChange = jest.fn()
    const options = [
      { value: 'val1', label: 'Label 1' },
      { value: 'val2', label: 'Label 2' }
    ]

    render(
      <SimpleSelect
        value="val1"
        onChange={onChange}
        options={options}
      />
    )

    expect(screen.getByText('Label 1')).toBeInTheDocument()
  })

  it('should have proper minimum touch target size', () => {
    render(
      <SimpleSelect
        value=""
        onChange={jest.fn()}
        options={['option1', 'option2']}
        className="test-select"
      />
    )

    const button = screen.getByRole('button')
    expect(button).toHaveClass('min-h-[44px]')
  })
})

